from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class CMLicensedHttpClient(HttpClient):
    """ This class provides a client for the CM Licensed API. """

    def __init__(self, base_url, connection_alias):
        super(CMLicensedHttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def download_current_plan(self, x_oam_client_type, include_runtime_data, include_auto_configured_data, timeout=30):
        """
        Name of this method is "download_current_plan" even though
        the underlying API endpoint for this operation contains "uploads" in its URL.

        This apparent inversion stems from a difference in perspective:
            *   API endpoints are typically named from the product's viewpoint
                (e.g., vDU offers an "upload" endpoint for user to download data from it).
            *   Library keywords are designed from the user's viewpoint (e.g., as a user, you are "downloading" a plan).

        This design choice prioritizes user-centric clarity within the library, abstracting the product's internal API naming conventions.
        """
        endpoint = '/current-plan/operations/uploads'
        headers = {
          "accept": "application/json",
          "Content-Type": "application/json",
          "X-OAM-Client-Type": x_oam_client_type,
        }
        data = {
          "includeRuntimeData": include_runtime_data,
          "includeAutoConfiguredData": include_auto_configured_data
        }

        return self._send_post_request(endpoint=endpoint, json=data, headers=headers, timeout=timeout)

    def get_download_plan_operation_status(self, just_id, timeout=30):
        """
        Name of this method is "get_download_plan_operation_status" even though
        the underlying API endpoint for this operation contains "uploads" in its URL.

        This apparent inversion stems from a difference in perspective:
            *   API endpoints are typically named from the product's viewpoint
                (e.g., vDU offers an "upload" endpoint for user to download data from it).
            *   Library keywords are designed from the user's viewpoint (e.g., as a user, you are "downloading" a plan).

        This design choice prioritizes user-centric clarity within the library, abstracting the product's internal API naming conventions.
        """
        endpoint = f'/current-plan/operations/uploads/{just_id}'
        headers = {
          "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_downloaded_plan_file(self, just_id, timeout=30):
        """
        Name of this method is "get_downloaded_plan_file" even though
        the underlying API endpoint for this operation contains "uploads" in its URL.

        This apparent inversion stems from a difference in perspective:
            *   API endpoints are typically named from the product's viewpoint
                (e.g., vDU offers an "upload" endpoint for user to download data from it).
            *   Library keywords are designed from the user's viewpoint (e.g., as a user, you are "downloading" a plan).

        This design choice prioritizes user-centric clarity within the library, abstracting the product's internal API naming conventions.
        """
        endpoint = f'/current-plan/operations/uploads/{just_id}/file'
        headers = {
          "accept": "application/xml",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
